import toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
import pluck = require( './index' );


// TESTS //

// The function returns an array...
{
	const arr = [
		{ 'a': 1, 'b': 2 },
		{ 'a': 0.5, 'b': 3 }
	];
	pluck( arr, 'a' ); // $ExpectType any[]
	pluck( toAccessorArray( arr ), 'a' ); // $ExpectType AccessorArrayLike<any>
}

// The compiler throws an error if the function is provided a first argument which is not an array...
{
	pluck( 'abc', 'a' ); // $ExpectError
	pluck( 123, 'a' ); // $ExpectError
	pluck( null, 'a' ); // $ExpectError
	pluck( {}, 'a' ); // $ExpectError
	pluck( ( x: number ): number => x, 'a' ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a valid property name...
{
	const arr = [
		{ 'a': 1, 'b': 2 },
		{ 'a': 0.5, 'b': 3 }
	];
	pluck( arr, true ); // $ExpectError
	pluck( arr, false ); // $ExpectError
	pluck( arr, [] ); // $ExpectError
	pluck( arr, {} ); // $ExpectError
	pluck( arr, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid number of arguments...
{
	const arr = [
		{ 'a': 1, 'b': 2 },
		{ 'a': 0.5, 'b': 3 }
	];
	pluck(); // $ExpectError
	pluck( arr ); // $ExpectError
	pluck( arr, 'a', { 'copy': true }, 2 ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns an array...
{
	const x = [
		{ 'a': 1, 'b': 2 },
		{ 'a': 0.5, 'b': 3 }
	];
	const y = [ 0, 0 ];

	pluck.assign( x, 'a', y, 1, 0 ); // $ExpectType any[]
	pluck.assign( toAccessorArray( x ), 'a', toAccessorArray( y ), 1, 0 ); // $ExpectType AccessorArrayLike<any>
}

// The compiler throws an error if the `assign` method is provided a first argument which is not an array...
{
	const y = [ 0, 0 ];

	pluck.assign( 'abc', 'a', y, 1, 0 ); // $ExpectError
	pluck.assign( 123, 'a', y, 1, 0 ); // $ExpectError
	pluck.assign( null, 'a', y, 1, 0 ); // $ExpectError
	pluck.assign( {}, 'a', y, 1, 0 ); // $ExpectError
	pluck.assign( ( x: number ): number => x, 'a', y, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a second argument which is not a valid property name...
{
	const arr = [
		{ 'a': 1, 'b': 2 },
		{ 'a': 0.5, 'b': 3 }
	];
	const y = [ 0, 0 ];

	pluck.assign( arr, true, y, 1, 0 ); // $ExpectError
	pluck.assign( arr, false, y, 1, 0 ); // $ExpectError
	pluck.assign( arr, [], y, 1, 0 ); // $ExpectError
	pluck.assign( arr, {}, y, 1, 0 ); // $ExpectError
	pluck.assign( arr, ( x: number ): number => x, y, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an invalid number of arguments...
{
	const arr = [
		{ 'a': 1, 'b': 2 },
		{ 'a': 0.5, 'b': 3 }
	];
	pluck(); // $ExpectError
	pluck( arr ); // $ExpectError
	pluck( arr, 'a', { 'copy': true }, 2 ); // $ExpectError
}
